pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address depositor, uint256 walletBalance, uint256 depositAmount) public {
        // Restrict depositAmount to a realistic range and walletBalance to avoid overflow
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(c));
        depositAmount = bound(depositAmount, 0, 10 ether);
        walletBalance = bound(walletBalance, 0, 100 ether);

        // Make exactly MinDeposit amount special by ensuring depositAmount is set to it
        // The fuzzer will explore many values; we test the invariant across all deposit amounts.
        // We want to check if exactly MinDeposit leads to balance change in correct vs buggy.
        // The invariant: if depositAmount > MinDeposit, balance increases; if depositAmount <= MinDeposit, balance stays same.
        // In the reference, depositAmount == MinDeposit is rejected. In the buggy, it is accepted.
        // So the universal rule: "After Deposit with msg.value = depositAmount, the balance of depositor increases only if depositAmount > MinDeposit"
        // We'll check that by comparing balance before and after.

        vm.deal(depositor, depositAmount + walletBalance);

        // Record starting balance
        uint256 balBefore = c.balances(depositor);

        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        uint256 balAfter = c.balances(depositor);

        if (depositAmount > c.MinDeposit()) {
            // Should have increased
            assertTrue(balAfter == balBefore + depositAmount);
        } else {
            // Should have stayed same
            assertTrue(balAfter == balBefore);
        }
    }
}

