pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address depositor, uint256 cashOutAmount) public {
        // Keep addresses realistic and non-zero
        vm.assume(depositor != address(0) && depositor != address(this) && depositor != address(c));
        // bound cashOutAmount to prevent overflow, but leave it wide enough to cover MinDeposit
        cashOutAmount = bound(cashOutAmount, 1, c.MinDeposit());

        // Use exactly MinDeposit as the deposit value
        uint256 depositValue = c.MinDeposit();
        vm.deal(depositor, depositValue);

        // Reference: deposit of exactly MinDeposit is rejected, balance stays 0
        // Buggy:    deposit of exactly MinDeposit is accepted, balance becomes depositValue
        vm.prank(depositor);
        c.Deposit{value: depositValue}();

        uint256 balanceBeforeCashOut = c.balances(depositor);

        // If buggy accepted deposit, balanceBeforeCashOut is depositValue;
        // if reference rejected, balanceBeforeCashOut is 0.
        // Now try to cash out `cashOutAmount` (bounded above by MinDeposit).
        // This call always succeeds because cashOutAmount <= MinDeposit <= balanceBeforeCashOut when non-zero,
        // and for reference with zero balance the if condition _am <= balances fails and does nothing.
        // In both cases no revert.
        vm.prank(depositor);
        c.CashOut(cashOutAmount);

        uint256 balanceAfterCashOut = c.balances(depositor);

        // General property for P (reference):
        // after a deposit of exactly MinDeposit followed by a CashOut of any amount <= MinDeposit,
        // the depositor's balance must be 0 (reference never changed it).
        // For M (buggy): if cashOutAmount == depositValue, balance drops from depositValue to 0.
        // To catch the difference we require that they differ AFTER CashOut:
        // In P, balanceAfterCashOut == 0 always. In M, balanceAfterCashOut == depositValue - cashOutAmount,
        // which can be non-zero (e.g. when cashOutAmount < depositValue).
        // Thus P's balances(depositor) == 0, M's != 0 for some input (fuzzer will find cashOutAmount < depositValue).
        assertTrue(balanceAfterCashOut == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address target, uint depAmount) public payable {
        require(address(this).balance >= depAmount);
        uint beforeBal = c.balances(target);
        c.Deposit{value: depAmount}();
        uint afterBal = c.balances(target);
        assert(depAmount > c.MinDeposit() ? afterBal > beforeBal : afterBal == beforeBal);
    }
    receive() external payable {}
}

